create table if not exists candidates(id text primary key,name text not null,handle text default '',bio text default '',photo_url text default '');
create table if not exists links(id text primary key,candidate_id text references candidates(id) on delete cascade,label text not null,url text not null,icon text default 'globe',position int default 0);
create table if not exists events(id bigint generated always as identity primary key,event_type text not null,candidate_id text,link_id text,path text,referrer text,user_agent text,ip_hash text,created_at timestamptz default now());
alter table candidates enable row level security;alter table links enable row level security;alter table events enable row level security;
create policy "public candidates" on candidates for select using(true);create policy "public links" on links for select using(true);
insert into candidates values('ana','Ana Carolina Serra','@anacarolinaserra','Advogada, professora e deputada estadual. Trabalho, cuidado e compromisso com São Paulo.',''),('paulo','Paulo Serra','@pauloserra','Economista, advogado e ex-prefeito de Santo André. Experiência para representar São Paulo.','') on conflict do nothing;
